package com.secman.service

import com.fasterxml.jackson.databind.ObjectMapper
import com.secman.dto.*
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import jakarta.inject.Singleton
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.net.URI
import java.nio.charset.CodingErrorAction
import java.security.MessageDigest
import java.time.Instant
import java.util.Base64
import javax.imageio.ImageIO

data class ValidatedIntegrationAttachment(val fileName: String, val contentType: String, val bytes: ByteArray)
data class ValidatedIntegrationRun(val request: IntegrationRunRequest, val digest: String, val findingsJson: String, val attachments: List<List<ValidatedIntegrationAttachment>>)

object IntegrationLifecycle {
    fun resolvesAbsent(run: IntegrationRunRequest) = run.status == "SUCCESS" && run.completeCoverage
    fun isNewer(run: IntegrationRunRequest, lastScanAt: Instant?) = lastScanAt == null || run.completedAt > lastScanAt
}

@Singleton
class IntegrationRunValidator(private val mapper: ObjectMapper) {
    companion object {
        val STATUSES = setOf("SUCCESS", "PARTIAL", "FAILED", "SKIPPED")
        val SEVERITIES = setOf("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO")
        val SOURCES = setOf("GITHUB_AI", "VISUAL")
        const val MAX_ATTACHMENT_BYTES = 1024 * 1024
        const val MAX_RUN_BYTES = 5 * MAX_ATTACHMENT_BYTES
    }

    fun validate(request: IntegrationRunRequest, now: Instant = Instant.now()): ValidatedIntegrationRun {
        check(request.scannerId > 0 && request.subjectId > 0, "Invalid scanner or subject")
        text(request.runKey, 128, true)
        check(request.runKey.matches(Regex("[A-Za-z0-9._:/-]+")), "Invalid run key")
        check(request.status in STATUSES, "Invalid status")
        check(request.startedAt >= Instant.parse("2000-01-01T00:00:00Z") &&
            request.startedAt <= request.completedAt && request.completedAt <= now.plusSeconds(300), "Invalid timestamps")
        check(request.findings.size <= 500, "At most 500 findings are allowed")
        check(request.findings.map { it.externalId }.toSet().size == request.findings.size, "Duplicate external IDs")
        text(request.metadataJson, 16000)
        check(parseJson(request.metadataJson).isObject, "metadataJson must be an object")
        var total = 0L
        val attachments = request.findings.map { finding ->
            validateFinding(finding)
            total += listOfNotNull(finding.description, finding.recommendation, finding.evidence).sumOf { it.toByteArray().size.toLong() }
            finding.attachments.map {
                val attachment = validateAttachment(it)
                total += attachment.bytes.size
                check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
                attachment
            }
        }
        check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
        // Hash the fixed DTO representation, so HTTP and MCP retries share a digest.
        val digest = MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(request))
            .joinToString("") { "%02x".format(it) }
        return ValidatedIntegrationRun(request, digest,
            mapper.writeValueAsString(request.findings.map { it.copy(attachments = emptyList()) }), attachments)
    }

    private fun validateFinding(f: IntegrationFindingInput) {
        text(f.externalId, 200, true)
        check(f.severity in SEVERITIES, "Invalid severity")
        text(f.title, 500, true)
        listOf(f.description, f.recommendation, f.evidence).forEach { text(it, 16000) }
        text(f.filePath, 1024); text(f.lineRange, 100); text(f.engine, 100); text(f.model, 200)
        text(f.commitSha, 64)
        listOf(f.url, f.issueUrl, f.fixPrUrl).forEach { url ->
            text(url, 2048)
            if (url != null) {
                val uri = try { URI(url) } catch (_: Exception) { invalid("Invalid URL") }
                check(uri.scheme in setOf("https", "http") && !uri.host.isNullOrBlank() && uri.userInfo == null, "Invalid URL")
            }
        }
        check(f.confidence == null || (f.confidence.isFinite() && f.confidence in 0.0..1.0), "Invalid confidence")
        check(f.legacyIds.size <= 10 && f.legacyIds.toSet().size == f.legacyIds.size, "Invalid legacy IDs")
        f.legacyIds.forEach { text(it, 255, true) }
        check(f.attachments.size <= 10, "At most 10 attachments per finding")
    }

    private fun validateAttachment(input: IntegrationAttachmentInput): ValidatedIntegrationAttachment {
        text(input.fileName, 200, true)
        check(input.fileName.matches(Regex("[A-Za-z0-9][A-Za-z0-9._ -]*")) && !input.fileName.contains(".."), "Invalid file name")
        val extensions = mapOf("image/png" to setOf("png"), "image/jpeg" to setOf("jpg", "jpeg"),
            "text/plain" to setOf("txt"), "application/json" to setOf("json"))
        check(input.fileName.substringAfterLast('.').lowercase() in (extensions[input.contentType] ?: emptySet()), "Invalid attachment type")
        check(input.base64.length <= ((MAX_ATTACHMENT_BYTES + 2) / 3) * 4, "Attachment exceeds 1 MiB")
        val bytes = try { Base64.getDecoder().decode(input.base64) } catch (_: IllegalArgumentException) { invalid("Invalid base64") }
        check(bytes.isNotEmpty() && bytes.size <= MAX_ATTACHMENT_BYTES, "Invalid attachment size")
        val safeBytes = if (input.contentType.startsWith("image/")) sanitizeImage(bytes, input.contentType) else {
            val decoded = try {
                Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(java.nio.ByteBuffer.wrap(bytes)).toString()
            } catch (_: Exception) { invalid("Attachment must be UTF-8") }
            check(decoded.none { it == '\u0000' }, "Invalid text attachment")
            if (input.contentType == "application/json") parseJson(decoded)
            bytes
        }
        check(safeBytes.size <= MAX_ATTACHMENT_BYTES, "Attachment exceeds 1 MiB after normalization")
        return ValidatedIntegrationAttachment(input.fileName, input.contentType, safeBytes)
    }

    private fun sanitizeImage(bytes: ByteArray, contentType: String): ByteArray {
        try {
            ImageIO.createImageInputStream(ByteArrayInputStream(bytes)).use { stream ->
                val readers = ImageIO.getImageReaders(stream)
                check(readers.hasNext(), "Invalid image")
                val reader = readers.next()
                try {
                    reader.input = stream
                    val format = reader.formatName.lowercase()
                    check(if (contentType == "image/png") format == "png" else format in setOf("jpeg", "jpg"), "Image type mismatch")
                    val width = reader.getWidth(0)
                    val height = reader.getHeight(0)
                    check(width in 1..8192 && height in 1..8192 && width.toLong() * height <= 16_000_000, "Image dimensions exceed limit")
                    val output = ByteArrayOutputStream()
                    check(ImageIO.write(reader.read(0), format, output), "Unsupported image")
                    return output.toByteArray()
                } finally { reader.dispose() }
            }
        } catch (e: HttpStatusException) { throw e
        } catch (_: Exception) { invalid("Invalid image") }
    }

    private fun parseJson(value: String) = try {
        mapper.readTree(value) ?: invalid("Invalid JSON")
    } catch (_: com.fasterxml.jackson.core.JsonProcessingException) { invalid("Invalid JSON") }

    private fun text(value: String?, max: Int, required: Boolean = false) {
        check(!required || !value.isNullOrBlank(), "Required text is missing")
        check(value == null || (value.length <= max && value.none { it == '\u0000' }), "Text exceeds limit or contains invalid characters")
    }
    private fun check(condition: Boolean, message: String) { if (!condition) invalid(message) }
    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
}
package com.secman.service

import com.secman.domain.*
import com.secman.dto.*
import com.secman.repository.IntegrationRepository
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import java.time.Instant

@Singleton
@Transactional
open class IntegrationReadService(private val repository: IntegrationRepository, private val access: IntegrationAccessService) {
    open fun scanners(auth: Authentication): List<IntegrationScannerDto> {
        val ids = access.assetIds(auth)
        val admin = "ADMIN" in auth.roles
        if (!admin && ids.isEmpty()) return emptyList()
        val where = if (admin) "1 = 1" else "EXISTS (SELECT s.id FROM IntegrationSubject s WHERE s.scannerId = x.id AND s.assetId IN :assets)"
        return repository.page(IntegrationScanner::class.java, "FROM IntegrationScanner x", where,
            if (admin) emptyMap() else mapOf("assets" to ids), 0, 100).content.map(IntegrationAdminService::scannerDto)
    }

    open fun subjects(scannerId: Long, page: Int, size: Int, auth: Authentication): IntegrationPage<IntegrationSubjectDto> {
        pagination(page, size)
        val ids = access.assetIds(auth)
        if (ids.isEmpty()) return emptyPage(page, size)
        val result = repository.page(IntegrationSubject::class.java, "FROM IntegrationSubject x",
            "x.scannerId = :scanner AND x.assetId IN :assets", mapOf("scanner" to scannerId, "assets" to ids), page, size)
        return mapped(result, subjectDtos(result.content))
    }

    open fun subject(id: Long, auth: Authentication): IntegrationSubjectDto {
        val subject = repository.find(IntegrationSubject::class.java, id) ?: access.notFound()
        access.requireAsset(subject.assetId, auth)
        return subjectDtos(listOf(subject)).single()
    }

    open fun runs(page: Int, size: Int, scannerId: Long?, subjectId: Long?, auth: Authentication): IntegrationPage<IntegrationRunDto> {
        pagination(page, size)
        val ids = access.assetIds(auth)
        if (ids.isEmpty()) return emptyPage(page, size)
        val params = mutableMapOf<String, Any>("assets" to ids)
        val predicates = mutableListOf("x.subjectId = s.id", "s.assetId IN :assets")
        scannerId?.let { predicates += "x.scannerId = :scanner"; params["scanner"] = it }
        subjectId?.let { predicates += "x.subjectId = :subject"; params["subject"] = it }
        val result = repository.page(IntegrationRun::class.java, "FROM IntegrationRun x, IntegrationSubject s",
            predicates.joinToString(" AND "), params, page, size)
        val subjects = repository.findMany(IntegrationSubject::class.java, result.content.map { it.subjectId }).associateBy { it.id }
        val assets = repository.findMany(Asset::class.java, subjects.values.map { it.assetId }).associateBy { it.id }
        val scanners = repository.findMany(IntegrationScanner::class.java, result.content.map { it.scannerId }).associateBy { it.id }
        return mapped(result, result.content.map { r ->
            IntegrationRunDto(r.id!!, r.scannerId, r.subjectId, scanners.getValue(r.scannerId).name,
                assets.getValue(subjects.getValue(r.subjectId).assetId).name, r.status, r.completeCoverage,
                r.startedAt, r.completedAt, r.accepted, r.resolved, r.metadataJson)
        })
    }

    open fun findings(page: Int, size: Int, filter: IntegrationFindingFilter, auth: Authentication): IntegrationPage<IntegrationFindingDto> {
        pagination(page, size)
        if (filter.source != null && filter.source !in IntegrationRunValidator.SOURCES ||
            filter.severity != null && filter.severity !in IntegrationRunValidator.SEVERITIES ||
            filter.state != null && filter.state !in setOf("OPEN", "RESOLVED") ||
            (filter.search?.length ?: 0) > 200 || (filter.owner?.length ?: 0) > 255) invalid("Invalid finding filter")
        val ids = access.assetIds(auth)
        if (ids.isEmpty()) return emptyPage(page, size)
        val params = mutableMapOf<String, Any>("assets" to ids)
        val predicates = mutableListOf("x.subjectId = s.id", "s.scannerId = c.id", "s.assetId = a.id", "s.assetId IN :assets")
        listOf("scanner" to filter.scannerId, "subject" to filter.subjectId, "repo" to filter.githubRepositoryId,
            "source" to filter.source, "owner" to filter.owner, "severity" to filter.severity, "state" to filter.state
        ).forEach { (key, value) ->
            if (value != null) {
                val column = mapOf("scanner" to "s.scannerId", "subject" to "s.id", "repo" to "s.githubRepositoryId",
                    "source" to "c.source", "owner" to "a.owner", "severity" to "x.severity", "state" to "x.state").getValue(key)
                predicates += "$column = :$key"; params[key] = value
            }
        }
        filter.search?.takeIf { it.isNotBlank() }?.let {
            predicates += "(LOCATE(:search, LOWER(x.title)) > 0 OR LOCATE(:search, LOWER(x.externalId)) > 0)"
            params["search"] = it.lowercase()
        }
        val result = repository.page(IntegrationFinding::class.java,
            "FROM IntegrationFinding x, IntegrationSubject s, IntegrationScanner c, Asset a",
            predicates.joinToString(" AND "), params, page, size)
        return mapped(result, findingDtos(result.content))
    }

    open fun finding(id: Long, auth: Authentication): IntegrationFindingDto {
        val finding = authorizedFinding(id, auth)
        return findingDtos(listOf(finding)).single()
    }

    open fun attachment(findingId: Long, attachmentId: Long, auth: Authentication): IntegrationAttachment {
        authorizedFinding(findingId, auth)
        val attachment = repository.find(IntegrationAttachment::class.java, attachmentId) ?: access.notFound()
        if (attachment.findingId != findingId) access.notFound()
        return attachment
    }

    open fun summary(auth: Authentication): IntegrationSummaryDto = summaryFor(access.assetIds(auth))

    /** Internal aggregate only; callers exposing this must enforce their ADMIN/SECCHAMPION policy. */
    open fun globalSummary(): IntegrationSummaryDto = summaryFor(null)

    private fun summaryFor(assetIds: Set<Long>?): IntegrationSummaryDto {
        if (assetIds?.isEmpty() == true) return IntegrationSummaryDto(0, 0, 0, 0, 0, 0, 0)
        val params = mutableMapOf<String, Any>()
        val scope = if (assetIds == null) "1 = 1" else "x.assetId IN :assets".also { params["assets"] = assetIds }
        val from = "FROM IntegrationSubject x, IntegrationScanner c"
        val base = "x.scannerId = c.id AND $scope"
        fun count(extra: String = "1 = 1", timed: Boolean = false) = repository.count(from, "$base AND $extra",
            if (timed) params + ("now" to Instant.now()) else params)
        val stale = "timestampadd(hour, c.staleAfterHours, coalesce(x.lastSuccessfulScanAt, x.createdAt)) < :now"
        val scannerScope = if (assetIds == null) "1 = 1" else
            "EXISTS (SELECT s.id FROM IntegrationSubject s WHERE s.scannerId = x.id AND s.assetId IN :assets)"
        val findingScope = if (assetIds == null) "1 = 1" else "s.assetId IN :assets"
        return IntegrationSummaryDto(
            repository.count("FROM IntegrationScanner x", scannerScope, params), count(),
            count("x.lastStatus = 'SUCCESS' AND NOT ($stale)", true), count("x.lastStatus IN ('FAILED', 'PARTIAL')"),
            count("x.lastScanAt IS NULL"), count("c.enabled = true AND $stale", true),
            repository.count("FROM IntegrationFinding x, IntegrationSubject s", "x.subjectId = s.id AND x.state = 'OPEN' AND $findingScope", params)
        )
    }

    private fun authorizedFinding(id: Long, auth: Authentication): IntegrationFinding {
        val finding = repository.find(IntegrationFinding::class.java, id) ?: access.notFound()
        val subject = repository.find(IntegrationSubject::class.java, finding.subjectId) ?: access.notFound()
        access.requireAsset(subject.assetId, auth)
        return finding
    }

    private fun subjectDtos(subjects: List<IntegrationSubject>): List<IntegrationSubjectDto> {
        val assets = repository.findMany(Asset::class.java, subjects.map { it.assetId }).associateBy { it.id }
        val scanners = repository.findMany(IntegrationScanner::class.java, subjects.map { it.scannerId }).associateBy { it.id }
        val repos = repository.findMany(GithubRepository::class.java, subjects.mapNotNull { it.githubRepositoryId }).associateBy { it.id }
        val counts = repository.openCounts(subjects.map { it.id!! })
        return subjects.map { s ->
            val a = assets.getValue(s.assetId)
            val c = scanners.getValue(s.scannerId)
            val r = repos[s.githubRepositoryId]
            IntegrationSubjectDto(s.id!!, s.scannerId, s.assetId, s.githubRepositoryId, a.name, a.uri, a.owner,
                r?.githubInstance, r?.githubRepoId, s.lastStatus, s.lastScanAt, s.lastSuccessfulScanAt,
                c.enabled && (s.lastSuccessfulScanAt ?: s.createdAt).plusSeconds(c.staleAfterHours * 3600L) < Instant.now(), counts[s.id] ?: 0)
        }
    }

    private fun findingDtos(findings: List<IntegrationFinding>): List<IntegrationFindingDto> {
        val subjects = repository.findMany(IntegrationSubject::class.java, findings.map { it.subjectId }).associateBy { it.id }
        val assets = repository.findMany(Asset::class.java, subjects.values.map { it.assetId }).associateBy { it.id }
        val scanners = repository.findMany(IntegrationScanner::class.java, subjects.values.map { it.scannerId }).associateBy { it.id }
        val projections = repository.findMany(Vulnerability::class.java, findings.mapNotNull { it.vulnerabilityId }).associateBy { it.id }
        val attachments = repository.attachmentMetadata(findings.map { it.id!! }).groupBy { it[0] as Long }
        return findings.map { f ->
            val s = subjects.getValue(f.subjectId); val a = assets.getValue(s.assetId); val c = scanners.getValue(s.scannerId)
            IntegrationFindingDto(f.id!!, c.id!!, c.name, c.source, s.id!!, a.name, a.id!!, s.githubRepositoryId, a.owner,
                f.externalId, f.severity, f.state, f.title, f.description, f.recommendation, f.evidence, f.filePath, f.lineRange,
                f.url, f.confidence, f.engine, f.model, f.commitSha, f.issueUrl, f.fixPrUrl,
                f.firstSeenAt, f.lastSeenAt, f.resolvedAt, f.vulnerabilityId?.takeIf { it in projections },
                projections[f.vulnerabilityId]?.excepted ?: false,
                attachments[f.id].orEmpty().map { IntegrationAttachmentDto(it[1] as Long, it[2] as String, it[3] as String) })
        }
    }

    private fun pagination(page: Int, size: Int) { if (page !in 0..100000 || size !in 1..100) invalid("Invalid pagination") }
    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
    private fun <T> emptyPage(page: Int, size: Int) = IntegrationPage<T>(emptyList(), 0, 0, page, size)
    private fun <T, R> mapped(page: IntegrationPage<T>, content: List<R>) = IntegrationPage(content, page.totalElements, page.totalPages, page.number, page.size)
}

