package com.secman.service

import com.secman.domain.*
import com.secman.dto.*
import com.secman.repository.IntegrationRepository
import com.secman.repository.UserRepository
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import org.slf4j.LoggerFactory

@Singleton
open class IntegrationAdminService(
    private val repository: IntegrationRepository,
    private val access: IntegrationAccessService,
    private val users: UserRepository
) {
    private val log = LoggerFactory.getLogger(IntegrationAdminService::class.java)

    @Transactional
    open fun saveScanner(id: Long?, request: IntegrationScannerRequest, auth: Authentication): IntegrationScannerDto {
        access.requireAdmin(auth)
        if (request.name.isBlank() || request.name.length > 200 || request.name.any { it.isISOControl() } ||
            request.source !in IntegrationRunValidator.SOURCES || request.staleAfterHours !in 1..8760 ||
            !users.existsById(request.serviceUserId)) invalid("Invalid scanner configuration")
        val scanner = id?.let { repository.lock(IntegrationScanner::class.java, it) ?: access.notFound() } ?: IntegrationScanner()
        if (id == null && repository.count("FROM IntegrationScanner x", "1 = 1", emptyMap()) >= 100) invalid("Scanner limit reached")
        if (id != null && scanner.source != request.source) invalid("Scanner source cannot be changed")
        scanner.name = request.name; scanner.source = request.source; scanner.serviceUserId = request.serviceUserId
        scanner.staleAfterHours = request.staleAfterHours; scanner.enabled = request.enabled
        if (id == null) repository.persist(scanner)
        log.info("Integration scanner saved: actorId={} scannerId={} outcome=success", users.findByUsername(auth.name).orElseThrow().id, scanner.id)
        return scannerDto(scanner)
    }

    @Transactional
    open fun bind(scannerId: Long, request: IntegrationSubjectRequest, auth: Authentication): Long {
        access.requireAdmin(auth)
        val scanner = repository.lock(IntegrationScanner::class.java, scannerId) ?: access.notFound()
        if ((request.assetId == null) == (request.githubRepositoryId == null)) invalid("Exactly one inventory ID is required")
        val repo = request.githubRepositoryId?.let { repository.lock(GithubRepository::class.java, it) ?: access.notFound() }
        if (repo != null && scanner.source != "GITHUB_AI") invalid("GitHub subjects require a GITHUB_AI scanner")
        val asset = if (repo != null) {
            repository.repositorySubject(repo.id!!)?.let { repository.find(Asset::class.java, it.assetId) }
                ?: resolveRepositoryAsset(repo, auth)
        } else {
            access.requireAsset(request.assetId!!, auth)
            repository.lock(Asset::class.java, request.assetId) ?: access.notFound()
        }
        access.requireAsset(asset.id!!, auth)
        repository.boundSubject(scannerId, asset.id!!)?.let { existing ->
            if (existing.githubRepositoryId != repo?.id) invalid("Asset already has a different binding")
            return existing.id!!
        }
        val subject = IntegrationSubject(scannerId = scannerId, assetId = asset.id!!, githubRepositoryId = repo?.id)
        repository.persist(subject)
        log.info("Integration subject bound: scannerId={} subjectId={} assetId={} outcome=success", scannerId, subject.id, asset.id)
        return subject.id!!
    }

    private fun resolveRepositoryAsset(repo: GithubRepository, auth: Authentication): Asset {
        val legacy = repository.legacyAssets(repo.fullName)
        // A name-only legacy match is safe only on the public instance; enterprise assets need a matching URI.
        val matching = legacy.filter { it.uri == repo.htmlUrl || (repo.githubInstance == "github.com" && it.uri.isNullOrBlank()) }
        if (legacy.size == 1 && matching.size == 1) {
            access.requireAsset(matching.single().id!!, auth)
            return matching.single()
        }
        val owner = repo.ownerEmail?.let { users.findByEmailIgnoreCase(it).orElse(null)?.username }
            ?: users.findByUsername(auth.name).orElseThrow().username
        val asset = Asset(name = repo.fullName.take(255), type = "REPOSITORY", owner = owner, uri = repo.htmlUrl)
        asset.manualCreator = users.findByUsername(auth.name).orElseThrow()
        repository.persist(asset)
        return asset
    }

    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
    companion object {
        fun scannerDto(s: IntegrationScanner) = IntegrationScannerDto(s.id!!, s.name, s.source, s.serviceUserId, s.staleAfterHours, s.enabled)
    }
}
package com.secman.repository

import com.secman.domain.*
import com.secman.dto.IntegrationPage
import jakarta.inject.Singleton
import jakarta.persistence.EntityManager
import jakarta.persistence.LockModeType

/** Persistence operations used inside the integration services' transactions. */
@Singleton
class IntegrationRepository(private val em: EntityManager) {
    fun <T : Any> findMany(type: Class<T>, ids: Collection<Long>): List<T> {
        if (ids.isEmpty()) return emptyList()
        val entity = when (type) {
            Asset::class.java -> "Asset"
            IntegrationScanner::class.java -> "IntegrationScanner"
            IntegrationSubject::class.java -> "IntegrationSubject"
            GithubRepository::class.java -> "GithubRepository"
            Vulnerability::class.java -> "Vulnerability"
            else -> error("Unsupported integration lookup")
        }
        return em.createQuery("FROM $entity x WHERE x.id IN :ids", type).setParameter("ids", ids).resultList
    }
    fun attachmentMetadata(findingIds: Collection<Long>): List<Array<Any>> {
        if (findingIds.isEmpty()) return emptyList()
        @Suppress("UNCHECKED_CAST")
        return em.createQuery("SELECT a.findingId, a.id, a.fileName, a.contentType FROM IntegrationAttachment a, IntegrationFinding f WHERE a.findingId = f.id AND a.runId = f.lastRunId AND f.id IN :ids ORDER BY a.id")
            .setParameter("ids", findingIds).resultList as List<Array<Any>>
    }
    fun openCounts(subjectIds: Collection<Long>): Map<Long, Long> {
        if (subjectIds.isEmpty()) return emptyMap()
        return em.createQuery("SELECT f.subjectId, COUNT(f) FROM IntegrationFinding f WHERE f.subjectId IN :ids AND f.state = 'OPEN' GROUP BY f.subjectId")
            .setParameter("ids", subjectIds).resultList.associate { row ->
                val values = row as Array<*>
                (values[0] as Long) to (values[1] as Long)
            }
    }
    fun <T : Any> find(type: Class<T>, id: Long): T? = em.find(type, id)
    fun <T : Any> lock(type: Class<T>, id: Long): T? = em.find(type, id, LockModeType.PESSIMISTIC_WRITE)
    fun scannerForSubmission(id: Long): IntegrationScanner? =
        em.find(IntegrationScanner::class.java, id, LockModeType.PESSIMISTIC_READ)
    fun persist(entity: Any) { em.persist(entity) }
    fun remove(entity: Any) { em.remove(entity) }
    fun flush() { em.flush() }

    fun replay(scannerId: Long, subjectId: Long, key: String): IntegrationRun? =
        em.createQuery("FROM IntegrationRun r WHERE r.scannerId = :scanner AND r.subjectId = :subject AND r.runKey = :key", IntegrationRun::class.java)
            .setParameter("scanner", scannerId).setParameter("subject", subjectId).setParameter("key", key).resultList.singleOrNull()

    fun finding(subjectId: Long, externalId: String): IntegrationFinding? =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.externalId = :external", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("external", externalId).resultList.singleOrNull()

    fun openFindingPage(subjectId: Long, afterId: Long): List<IntegrationFinding> =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.state = 'OPEN' AND f.id > :after ORDER BY f.id", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("after", afterId).setMaxResults(500).resultList

    fun legacyCandidates(assetId: Long, legacyIds: List<String>): List<Vulnerability> =
        if (legacyIds.isEmpty()) emptyList() else em.createQuery(
            "FROM Vulnerability v WHERE v.asset.id = :asset AND v.vulnerabilityId IN :ids", Vulnerability::class.java
        ).setParameter("asset", assetId).setParameter("ids", legacyIds).setMaxResults(11).resultList

    fun projectionClaimed(id: Long): Boolean = em.createQuery(
        "SELECT COUNT(f) FROM IntegrationFinding f WHERE f.vulnerabilityId = :id", Long::class.javaObjectType
    ).setParameter("id", id).singleResult > 0

    fun legacyIdentityClaimed(assetId: Long, ids: List<String>): Boolean =
        if (ids.isEmpty()) false else em.createQuery(
            "SELECT COUNT(f) FROM IntegrationFinding f, IntegrationSubject s WHERE f.subjectId = s.id AND s.assetId = :asset AND f.projectionKey IN :ids",
            Long::class.javaObjectType
        ).setParameter("asset", assetId).setParameter("ids", ids).singleResult > 0

    fun attachments(findingId: Long, runId: Long): List<IntegrationAttachment> = em.createQuery(
        "FROM IntegrationAttachment a WHERE a.findingId = :finding AND a.runId = :run ORDER BY a.id", IntegrationAttachment::class.java
    ).setParameter("finding", findingId).setParameter("run", runId).setMaxResults(10).resultList

    // Only service-owned JPQL fragments reach these methods; all request values are parameters.
    fun <T : Any> page(type: Class<T>, from: String, where: String, params: Map<String, Any>, page: Int, size: Int): IntegrationPage<T> {
        require(page in 0..100000 && size in 1..100) { "Invalid pagination" }
        val query = em.createQuery("SELECT x $from WHERE $where ORDER BY x.id DESC", type)
        val count = em.createQuery("SELECT COUNT(x) $from WHERE $where", Long::class.javaObjectType)
        params.forEach { (name, value) -> query.setParameter(name, value); count.setParameter(name, value) }
        val total = count.singleResult
        return IntegrationPage(query.setFirstResult(page * size).setMaxResults(size).resultList,
            total, ((total + size - 1) / size).toInt(), page, size)
    }

    fun count(from: String, where: String, params: Map<String, Any>): Long {
        val query = em.createQuery("SELECT COUNT(x) $from WHERE $where", Long::class.javaObjectType)
        params.forEach { (name, value) -> query.setParameter(name, value) }
        return query.singleResult
    }

    fun boundSubject(scannerId: Long, assetId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.scannerId = :scanner AND s.assetId = :asset", IntegrationSubject::class.java
    ).setParameter("scanner", scannerId).setParameter("asset", assetId).resultList.singleOrNull()

    fun repositorySubject(repositoryId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.githubRepositoryId = :repo ORDER BY s.id", IntegrationSubject::class.java
    ).setParameter("repo", repositoryId).setMaxResults(1).resultList.firstOrNull()

    fun legacyAssets(name: String): List<Asset> = em.createQuery(
        "FROM Asset a WHERE a.name = :name", Asset::class.java
    ).setParameter("name", name).setMaxResults(2).resultList
}
