    <div className="card-header d-flex justify-content-between align-items-center">
      <h3 className="h5 mb-0">{finding.title}</h3>
      <button className="btn btn-sm btn-outline-secondary" onClick={onClose}>Close details</button>
    </div>
    <div className="card-body">
      <p>{finding.severity} · {finding.state} · {finding.scannerName} · {finding.excepted ? 'Covered by an exception' : 'No active exception'}</p>
      <p><a href={`/assets/${finding.assetId}`}>{finding.subjectName}</a> · Owner: {finding.owner || 'Unassigned'}</p>
      <dl className="row small">
        <dt className="col-sm-3">First observed</dt><dd className="col-sm-9">{formatServerDate(finding.firstSeenAt)}</dd>
        <dt className="col-sm-3">Last observed</dt><dd className="col-sm-9">{formatServerDate(finding.lastSeenAt)}</dd>
        {finding.resolvedAt && <><dt className="col-sm-3">Resolved</dt><dd className="col-sm-9">{formatServerDate(finding.resolvedAt)}</dd></>}
        {finding.filePath && <><dt className="col-sm-3">Location</dt><dd className="col-sm-9 text-break">{finding.filePath} {finding.lineRange}</dd></>}
        {(finding.engine || finding.model) && <><dt className="col-sm-3">Scanner engine / model</dt><dd className="col-sm-9">{finding.engine} {finding.model}</dd></>}
        {finding.commitSha && <><dt className="col-sm-3">Commit</dt><dd className="col-sm-9 text-break">{finding.commitSha}</dd></>}
        {finding.confidence != null && <><dt className="col-sm-3">Confidence</dt><dd className="col-sm-9">{Math.round(finding.confidence * 100)}%</dd></>}
      </dl>
      {[['Description', finding.description], ['Recommendation', finding.recommendation], ['Evidence', finding.evidence]].map(([label, value]) => value &&
        <div className="mb-3" key={label}><h4 className="h6">{label}</h4><div className="text-break" style={{ whiteSpace: 'pre-wrap' }}>{value}</div></div>)}
      <div className="d-flex flex-wrap gap-3 mb-3">
        <EvidenceLink value={finding.url} label="Source page" />
        <EvidenceLink value={finding.issueUrl} label="Issue" />
        <EvidenceLink value={finding.fixPrUrl} label="Fix pull request" />
        {finding.vulnerabilityId != null && <a href={`/assets/${finding.assetId}`}>Manage vulnerability and request an exception</a>}
      </div>
      {finding.attachments?.length > 0 && <><h4 className="h6">Attachments</h4><ul className="list-unstyled">
        {finding.attachments.map(attachment => <li key={attachment.id} className="mb-1"><button className="btn btn-link p-0" onClick={() => {
          setError('');
          downloadIntegrationAttachment(finding.id, attachment.id, attachment.fileName).catch(err => setError(err instanceof Error ? err.message : 'Download failed.'));
        }}>{attachment.fileName}</button> <span className="text-muted small">{attachment.contentType}</span></li>)}
      </ul></>}
      {error && <p className="text-danger" role="alert">{error}</p>}
    </div>
  </section>;
}

export default function IntegrationFindingList({ githubRepositoryId, scannerId, refresh = 0 }: { githubRepositoryId?: number; scannerId?: number; refresh?: number }) {
  const [filters, setFilters] = useState<FindingFilters>({ state: 'OPEN' });
  const [page, setPage] = useState(0);
  const [data, setData] = useState<IntegrationPage<IntegrationFinding> | null>(null);
  const [selected, setSelected] = useState<IntegrationFinding | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const query = JSON.stringify({ ...filters, githubRepositoryId, scannerId });
  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    setSelected(null);
    getIntegrationFindings(JSON.parse(query), page)
      .then(result => { if (active) setData(result); })
      .catch(err => { if (active) setError(err instanceof Error ? err.message : 'Could not load findings.'); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [query, page, refresh]);

  const update = (key: keyof FindingFilters, value: string) => {
    setPage(0);
    setFilters(previous => ({ ...previous, [key]: value }));
  };
  const showDetail = async (id: number) => {
    setDetailLoading(true);
    try { setSelected(await getIntegrationFinding(id)); }
    catch (err) { setError(err instanceof Error ? err.message : 'Could not load finding.'); }
    finally { setDetailLoading(false); }
  };

  return <section aria-label={githubRepositoryId ? 'AI repository findings' : 'Integration findings'}>
    <h2 className="h5">{githubRepositoryId ? 'AI scanner findings' : 'Findings'} {data && <span className="text-muted">({data.totalElements})</span>}</h2>
    {githubRepositoryId && <p className="small text-muted">Scanner observations are shown separately from Dependabot alerts.</p>}
    <div className="row g-2 mb-3">
      <div className="col-md"><label className="form-label small" htmlFor={`finding-search-${githubRepositoryId || 'all'}`}>Search</label><input id={`finding-search-${githubRepositoryId || 'all'}`} className="form-control form-control-sm" value={filters.search || ''} onChange={e => update('search', e.target.value)} placeholder="Title or subject" /></div>
      {!githubRepositoryId && <div className="col-md"><label className="form-label small">Source<select className="form-select form-select-sm" value={filters.source || ''} onChange={e => update('source', e.target.value)}><option value="">All sources</option><option value="GITHUB_AI">GitHub AI</option><option value="VISUAL">Visual scanner</option></select></label></div>}
      <div className="col-md"><label className="form-label small">Owner<input className="form-control form-control-sm" value={filters.owner || ''} onChange={e => update('owner', e.target.value)} placeholder="Owner name" /></label></div>
      <div className="col-md"><label className="form-label small">Severity<select className="form-select form-select-sm" value={filters.severity || ''} onChange={e => update('severity', e.target.value)}><option value="">All severities</option>{['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO'].map(value => <option key={value}>{value}</option>)}</select></label></div>
      <div className="col-md"><label className="form-label small">State<select className="form-select form-select-sm" value={filters.state || ''} onChange={e => update('state', e.target.value)}><option value="">All states</option><option>OPEN</option><option>RESOLVED</option></select></label></div>
    </div>
    {error && <div className="alert alert-danger" role="alert">{error}</div>}
    {loading ? <p role="status">Loading findings…</p> : !error && <>
      <div className="table-responsive"><table className="table table-striped align-middle"><thead><tr><th>Finding</th><th>Subject / owner</th><th>Severity</th><th>State</th><th>Last observed</th></tr></thead><tbody>
        {data?.content.map(finding => <tr key={finding.id}>
          <td><button className="btn btn-link p-0 text-start" disabled={detailLoading} onClick={() => showDetail(finding.id)}>{finding.title}</button><div className="text-muted small">{finding.scannerName}</div></td>
          <td><a href={`/assets/${finding.assetId}`}>{finding.subjectName}</a><div className="small text-muted">{finding.owner || 'Unassigned'}</div></td>
          <td><span className={`badge ${['CRITICAL', 'HIGH'].includes(finding.severity) ? 'bg-danger' : 'bg-secondary'}`}>{finding.severity}</span></td>
          <td>{finding.state}{finding.excepted && <div className="small text-muted">Excepted</div>}</td><td>{formatServerDate(finding.lastSeenAt)}</td>
        </tr>)}
        {!data?.content.length && <tr><td colSpan={5} className="text-muted py-3">No findings match these filters. Check scan coverage before interpreting this as a clean result.</td></tr>}
      </tbody></table></div>
      {data && <Pagination currentPage={page} totalPages={data.totalPages} totalElements={data.totalElements} pageSize={25} onPageChange={setPage} />}
    </>}
    {detailLoading && <p role="status">Loading evidence…</p>}
    {selected && <IntegrationFindingDetail finding={selected} onClose={() => setSelected(null)} />}
  </section>;
}
import React, { useEffect, useState } from 'react';
import { getIntegrationSummary, getScanners, getIntegrationSubjects, getIntegrationRuns, type Scanner, type IntegrationSummary, type IntegrationSubject, type IntegrationRun, type IntegrationPage } from '../services/integrationsService';
import { coverageLabel } from '../services/integrationPresentation';
import { hasRole } from '../utils/auth';
import { formatServerDate } from '../utils/dateUtils';
import IntegrationFindingList from './IntegrationFindingList';
import IntegrationScannerConfig from './IntegrationScannerConfig';
import Pagination from './Pagination';

export default function IntegrationDashboard() {
  const [summary, setSummary] = useState<IntegrationSummary | null>(null);
  const [scanners, setScanners] = useState<Scanner[]>([]);
  const [scannerId, setScannerId] = useState<number | undefined>();
  const [subjects, setSubjects] = useState<IntegrationPage<IntegrationSubject> | null>(null);
  const [runs, setRuns] = useState<IntegrationPage<IntegrationRun> | null>(null);
  const [subjectPage, setSubjectPage] = useState(0);
  const [runPage, setRunPage] = useState(0);
  const [tab, setTab] = useState('findings');
  const [admin, setAdmin] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [expandedRun, setExpandedRun] = useState<number | null>(null);
  useEffect(() => { setAdmin(hasRole('ADMIN')); }, []);
  useEffect(() => {
    let active = true;
    setLoading(true); setError('');
    Promise.all([getIntegrationSummary(), getScanners()])
      .then(([nextSummary, nextScanners]) => { if (active) { setSummary(nextSummary); setScanners(nextScanners); } })
      .catch(err => { if (active) setError(err instanceof Error ? err.message : 'Could not load integrations.'); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [refresh]);
  useEffect(() => {
    let active = true;
    if (tab === 'targets' && scannerId) {
      setSubjects(null); setError('');
      getIntegrationSubjects(scannerId, subjectPage).then(data => { if (active) setSubjects(data); })
        .catch(err => { if (active) setError(err instanceof Error ? err.message : 'Could not load targets.'); });
    }
    if (tab === 'runs') {
      setRuns(null); setError('');
      getIntegrationRuns(scannerId, runPage).then(data => { if (active) setRuns(data); })
        .catch(err => { if (active) setError(err instanceof Error ? err.message : 'Could not load scan history.'); });
    }
    return () => { active = false; };
  }, [scannerId, tab, subjectPage, runPage, refresh]);
  const current = scanners.find(scanner => scanner.id === scannerId);
  const cards: [string, number][] = summary ? [
    ['Open findings', summary.openFindings], ['Registered targets', summary.totalSubjects],
    ['Current', summary.healthySubjects], ['Failed', summary.failedSubjects],
    ['Stale', summary.staleSubjects], ['Not scanned', summary.unscannedSubjects],
  ] : [];
  return <div className="container-fluid py-4">
    <header className="d-flex justify-content-between align-items-center mb-4"><div><h1 className="h3">Integration results</h1><p className="text-muted mb-0">Findings, evidence and scan coverage from your security scanners.</p></div><button className="btn btn-outline-primary" onClick={() => setRefresh(value => value + 1)}>Refresh</button></header>
    {error && <div className="alert alert-danger" role="alert">{error}</div>}
    {loading ? <p role="status">Loading scanner coverage…</p> : <div className="row g-3 mb-4">{cards.map(([label, count]) => <div className="col-6 col-lg-2" key={label}><div className="card h-100"><div className="card-body"><div className="fs-3 fw-semibold">{count}</div><div className="text-muted small">{label}</div></div></div></div>)}</div>}
    <p className="small text-muted">An empty finding list does not prove a clean scan. Review target coverage and failed or incomplete runs. Stale and failed counts may overlap.</p>
    <label className="form-label mb-3">Scanner<select className="form-select" value={scannerId || ''} onChange={e => { setScannerId(e.target.value ? Number(e.target.value) : undefined); setSubjectPage(0); setRunPage(0); }}><option value="">All scanners</option>{scanners.map(scanner => <option key={scanner.id} value={scanner.id}>{scanner.name}{scanner.enabled ? '' : ' (disabled)'}</option>)}</select></label>
    <ul className="nav nav-tabs mb-3">{[['findings', 'Findings'], ['targets', 'Target coverage'], ['runs', 'Scan history'], ...(admin ? [['settings', 'Scanner settings']] : [])].map(([key, title]) => <li className="nav-item" key={key}><button className={`nav-link ${tab === key ? 'active' : ''}`} onClick={() => setTab(key)}>{title}</button></li>)}</ul>
    {tab === 'findings' && <IntegrationFindingList scannerId={scannerId} refresh={refresh} />}
    {tab === 'settings' && admin && <IntegrationScannerConfig key={scannerId || 'new'} scanner={current} onSaved={() => setRefresh(value => value + 1)} />}
    {tab === 'targets' && (!scannerId ? <p>Select a scanner to review its registered targets.</p> : !subjects ? !error && <p role="status">Loading targets…</p> : <>
      <div className="table-responsive"><table className="table table-striped"><thead><tr><th>Target</th><th>Owner</th><th>Coverage</th><th>Last scan</th><th>Last success</th><th>Open findings</th></tr></thead><tbody>{subjects.content.map(subject => <tr key={subject.id}><td><a href={`/assets/${subject.assetId}`}>{subject.name}</a></td><td>{subject.owner || 'Unassigned'}</td><td>{coverageLabel(subject)}</td><td>{formatServerDate(subject.lastScanAt, undefined, 'Never')}</td><td>{formatServerDate(subject.lastSuccessfulScanAt, undefined, 'Never')}</td><td>{subject.openFindings}</td></tr>)}{!subjects.content.length && <tr><td colSpan={6}>No registered targets. {admin && 'Register targets in scanner settings.'}</td></tr>}</tbody></table></div>
      <Pagination currentPage={subjectPage} totalPages={subjects.totalPages} totalElements={subjects.totalElements} pageSize={25} onPageChange={setSubjectPage} />
    </>)}
    {tab === 'runs' && (!runs ? !error && <p role="status">Loading scan history…</p> : <>
      <div className="table-responsive"><table className="table table-striped"><thead><tr><th>Scanner / target</th><th>Result</th><th>Coverage</th><th>Completed</th><th>Accepted / resolved</th><th>Evidence</th></tr></thead><tbody>{runs.content.map(run => <React.Fragment key={run.id}><tr><td>{run.scannerName}<div className="small text-muted">{run.subjectName}</div></td><td>{run.status}</td><td>{run.completeCoverage ? 'Complete' : 'Incomplete; missing findings retained'}</td><td>{formatServerDate(run.completedAt)}</td><td>{run.accepted} / {run.resolved}</td><td><button className="btn btn-sm btn-outline-secondary" onClick={() => setExpandedRun(expandedRun === run.id ? null : run.id)}>Run details</button></td></tr>{expandedRun === run.id && <tr><td colSpan={6}><pre className="text-wrap text-break mb-0">{run.metadataJson || 'No additional scan metadata.'}</pre></td></tr>}</React.Fragment>)}{!runs.content.length && <tr><td colSpan={6}>No scans have been received for this selection.</td></tr>}</tbody></table></div>
      <Pagination currentPage={runPage} totalPages={runs.totalPages} totalElements={runs.totalElements} pageSize={25} onPageChange={setRunPage} />
    </>)}
  </div>;
}
"}

