                candidates[external_id] = (payload, attachment, size)

    evidence_bytes = 0
    findings: list[dict[str, Any]] = []
    for external_id in sorted(candidates)[:500]:
        payload, attachment, attachment_size = candidates[external_id]
        for field in ("description", "recommendation", "evidence"):
