def _result_status(result: dict[str, Any]) -> str:
    if result.get("skipped_reason"):
        return "SKIPPED"
    capture = result.get("capture")
    analysis = result.get("analysis")
    if (
        result.get("error")
        or (isinstance(capture, dict) and capture.get("load_error"))
        or (isinstance(analysis, dict) and analysis.get("error"))
    ):
        return "FAILED"
    return "SUCCESS"


def _aggregate_status(results: Sequence[dict[str, Any]]) -> str:
    statuses = {_result_status(result) for result in results}
    if statuses == {"SUCCESS"}:
        return "SUCCESS"
    if statuses == {"FAILED"}:
        return "FAILED"
    if statuses == {"SKIPPED"}:
        return "SKIPPED"
    return "PARTIAL"


def _normal_uri(value: Any) -> str:
    return str(value or "").strip().rstrip("/").lower()


def _subject_for_result(
    result: dict[str, Any],
    subjects: Sequence[dict[str, Any]],
    asset_override: str | None,
) -> dict[str, Any]:
    url = str(result.get("url") or "").strip()
    if not url:
        raise SecmanError("scan result has no URL and cannot be matched to a subject")
    if asset_override:
        matches = [
            row
            for row in subjects
            if str(row.get("name") or "").strip().lower() == asset_override.lower()
        ]
    else:
        host = urlparse(url).hostname
        if not host:
            raise SecmanError(f"cannot match hostless target {url!r} to an integration subject")
        matches = [
            row
            for row in subjects
            if str(row.get("name") or "").strip().lower() == host.lower()
        ]
        if not matches:
            matches = [row for row in subjects if _normal_uri(row.get("uri")) == _normal_uri(url)]
    if not matches:
        raise SecmanError(f"no subject for target {url!r} in the configured scanner")
    if len(matches) > 1:
        raise SecmanError(f"multiple subjects match target {url!r}; refusing to guess")
    return matches[0]


def _status_metadata(status: Any) -> dict[str, Any] | None:
    if not isinstance(status, dict):
        return None
    redirects = []
    for hop in status.get("chain") or []:
        if isinstance(hop, dict):
            redirects.append(
                {
                    "url": hop.get("url"),
                    "status": hop.get("status"),
                    "location": hop.get("location"),
                }
            )
    return {


def _integration_external_id(legacy_id: str) -> str:
    if len(legacy_id) <= 200:
        return legacy_id
    # Keep the digest that carries the full URL/category identity when the
    # readable category label must be shortened to the v1 field limit.
    return f"{legacy_id[:189]}-{legacy_id[-10:]}"


def _finding_payloads(
    results: Sequence[dict[str, Any]], id_prefix: str, default_model: str
) -> list[dict[str, Any]]:
    candidates: dict[str, tuple[dict[str, Any], dict[str, Any] | None, int]] = {}
    for result in sorted(results, key=lambda row: str(row.get("url") or "")):
        url = str(result.get("url") or "")
        analysis = result.get("analysis")
        if not isinstance(analysis, dict):
            continue
        capture = result.get("capture")
        attachment, size = _image_attachment(
            capture.get("screenshot_path") if isinstance(capture, dict) else None
        )
        for raw in analysis.get("findings") or []:
            if not isinstance(raw, dict) or not str(raw.get("title") or "").strip():
                continue
            category = str(raw.get("category") or "other").strip() or "other"
            legacy_id = vulnerability_id(url, category, id_prefix)
            external_id = _integration_external_id(legacy_id)
            severity = Severity.parse(raw.get("severity"), Severity.MEDIUM)
            payload = {
                "externalId": external_id,
                "legacyIds": [legacy_id],
                "severity": severity.value.upper(),
                "title": str(raw.get("title") or "").strip()[:500],
                "description": str(analysis.get("summary") or "")[:16000],
                "recommendation": str(raw.get("recommendation") or "")[:16000],
                "evidence": str(raw.get("evidence") or "")[:16000],
                "filePath": None,
                "lineRange": None,
                "url": url[:2048],
                "confidence": float(raw.get("confidence") or 0.0),
                "engine": CLIENT_NAME,
                "model": (str(analysis.get("model") or default_model)[:200] or None),
                "commitSha": None,
                "issueUrl": None,
                "fixPrUrl": None,
                "attachments": [],
            }
            current = candidates.get(external_id)
            if current is None or severity.rank > Severity.parse(current[0]["severity"]).rank:
                candidates[external_id] = (payload, attachment, size)

    evidence_bytes = 0
    findings: list[dict[str, Any]] = []
    for external_id in sorted(candidates)[:500]:
        payload, attachment, attachment_size = candidates[external_id]
        for field in ("description", "recommendation", "evidence"):
            remaining = _MAX_RUN_ATTACHMENT_BYTES - evidence_bytes
            payload[field] = _clip_bytes(payload[field], 16000, max(0, remaining))
            evidence_bytes += len(payload[field].encode("utf-8"))
        if (
            attachment is not None
            and evidence_bytes + attachment_size <= _MAX_RUN_ATTACHMENT_BYTES
        ):
            payload["attachments"] = [attachment]
            evidence_bytes += attachment_size
        findings.append(payload)
    return findings


def _metadata_json(data: dict[str, Any], results: Sequence[dict[str, Any]]) -> str:
    target_rows = [_target_metadata(row) for row in results]
    counts = {status: 0 for status in ("SUCCESS", "FAILED", "SKIPPED")}
    for row in target_rows:
        counts[row["outcome"]] += 1
    metadata: dict[str, Any] = {
        "tool": CLIENT_NAME,
        "toolVersion": str(data.get("tool_version") or "")[:100],
        "model": str(data.get("model") or "")[:200],
        "targetCount": len(target_rows),
        "outcomeCounts": counts,
        "targetsOmitted": len(target_rows),
        "targets": [],
    }
    for row in target_rows:
        metadata["targets"].append(row)
        metadata["targetsOmitted"] -= 1
        encoded = json.dumps(metadata, sort_keys=True, separators=(",", ":"))
        if len(encoded) > 16000:
            metadata["targets"].pop()
            metadata["targetsOmitted"] += 1
            break
    return json.dumps(metadata, sort_keys=True, separators=(",", ":"))


def build_integration_run_requests(
    report: dict[str, Any] | ScanReport,
    scanner_id: int,
    subjects: Sequence[dict[str, Any]],
    *,
    id_prefix: str = DEFAULT_ID_PREFIX,
    asset_override: str | None = None,
) -> list[dict[str, Any]]:
    """Map one visual report into one atomic version-1 request per subject.

    Visual scans know which pages they were given, not every page belonging to
    an inventory asset. They therefore never infer complete asset coverage.
    """
    data = report.to_dict() if isinstance(report, ScanReport) else report
    results = data.get("results")
    if not isinstance(results, list):
        raise SecmanError("report has no 'results' list; is this a secman_visual_check report?")
    grouped: dict[int, tuple[dict[str, Any], list[dict[str, Any]]]] = {}
    for raw in results:
        if not isinstance(raw, dict):
