    bodies: list[dict[str, Any]] = []
    for subject_id in sorted(grouped):
        _, subject_results = grouped[subject_id]
        body: dict[str, Any] = {
            "scannerId": scanner_id,
            "subjectId": subject_id,
            "status": _aggregate_status(subject_results),
            "completeCoverage": False,
            "startedAt": data.get("started_at"),
            "completedAt": data.get("finished_at"),
            "metadataJson": _metadata_json(data, subject_results),
            "findings": _finding_payloads(
                subject_results, id_prefix, str(data.get("model") or "")
            ),
        }
        digest = hashlib.sha256(
            json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()[:24]
        body["runKey"] = f"visual-v1-{scanner_id}-{subject_id}-{digest}"
        bodies.append(body)
    return bodies


